const $=s=>document.querySelector(s);
const yen=n=>'¥'+n.toLocaleString('ja-JP');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stateKey='card-port-store-v1';
let game='ポケモンカード',cart={},orders=[],stateRevision=null,storageBroken=false;
try{stateRevision=localStorage.getItem(stateKey);if(stateRevision){const s=JSON.parse(stateRevision);if(!Array.isArray(s.products)||!Array.isArray(s.orders)||!s.cart)throw Error('Invalid state');PRODUCTS.splice(0,PRODUCTS.length,...s.products);orders=s.orders;cart=s.cart}else{cart=JSON.parse(localStorage.getItem('card-port-cart')||'{}')}}catch{storageBroken=true}
function normalizeCart(){for(const id of Object.keys(cart)){const p=PRODUCTS.find(p=>p.id===id);if(!p||!Number.isInteger(cart[id])||cart[id]<1||p.stock<1)delete cart[id];else cart[id]=Math.min(cart[id],p.stock)}}
function writeState(products=PRODUCTS,nextOrders=orders,nextCart=cart){try{if(storageBroken)throw Error('Storage unavailable');if(localStorage.getItem(stateKey)!==stateRevision){toast('別のタブで変更されています。ページを再読み込みしてください。');return false}const value=JSON.stringify({products,orders:nextOrders,cart:nextCart});localStorage.setItem(stateKey,value);stateRevision=value;return true}catch{toast('保存できませんでした。ブラウザーの保存設定・空き容量を確認してください。');return false}}
function save(){const ok=writeState();$('#cart-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);return ok}
normalizeCart();
function render(){const term=$('#search').value.trim().toLowerCase(),price=$('#price').value,type=document.querySelector('[name=type]:checked').value;let list=PRODUCTS.filter(p=>p.game===game&&p.name.toLowerCase().includes(term)&&(type==='all'||p.type===type)&&(!$('#in-stock').checked||p.stock>0)&&(price==='all'||price==='low'&&p.price<1000||price==='mid'&&p.price>=1000&&p.price<5000||price==='high'&&p.price>=5000));const sort=$('#sort').value;if(sort==='price-asc')list.sort((a,b)=>a.price-b.price);if(sort==='price-desc')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ja'));$('#results-count').textContent=list.length;$('#products').innerHTML=list.map((p,i)=>`<article class="product"><button class="image-button" data-detail="${esc(p.id)}" aria-label="${esc(p.name)}の詳細"><span class="badge ${p.badge==='NEW'?'new':''}">${esc(p.badge)}</span>${productImage(p,i>2)}</button><p class="product-meta">${esc(p.series)} · ${esc(p.rarity)}</p><button class="product-name" data-detail="${esc(p.id)}">${esc(p.name)}</button><div class="price-row"><span class="price">${yen(p.price)}<small>税込</small></span><span class="stock ${p.stock?'':'sold'}">${p.stock?'在庫あり':'SOLD OUT'}</span></div><button class="add" data-add="${esc(p.id)}" ${p.stock?'':'disabled'}>${p.stock?'＋ カートに入れる':'売り切れ'}</button></article>`).join('');$('#empty').hidden=!!list.length;$('#catalog-name').textContent=game;$('#crumb').textContent=game}
function reset(){game='ポケモンカード';$('#search').value='';$('#price').value='all';$('#sort').value='featured';$('#in-stock').checked=false;document.querySelector('[name=type][value=all]').checked=true;document.querySelectorAll('[data-game]').forEach(b=>b.classList.toggle('active',b.dataset.game===game));render()}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function add(id){const p=PRODUCTS.find(p=>p.id===id);if(!p)return;if((cart[id]||0)>=p.stock){toast('デモ在庫の上限に達しました');return}const previous=cart[id]||0;cart[id]=previous+1;if(!save()){if(previous)cart[id]=previous;else delete cart[id];$('#cart-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);return}toast('カートに追加しました');if($('#cart-dialog').open)renderCart()}
function renderCart(){normalizeCart();$('#checkout').disabled=!Object.keys(cart).length;$('#cart-items').innerHTML=Object.entries(cart).map(([id,q])=>{const p=PRODUCTS.find(p=>p.id===id);return `<div class="cart-row">${productImage(p)}<div class="cart-row-content"><h3>${esc(p.name)}</h3><p>${yen(p.price)} × ${q}</p><div class="quantity"><button data-minus="${id}" aria-label="${esc(p.name)}を1枚減らす">−</button><span>${q}</span><button data-add="${id}" aria-label="${esc(p.name)}を1枚増やす" ${q>=p.stock?'disabled':''}>＋</button></div></div><button class="remove" data-remove="${id}">削除</button></div>`}).join('')||'<p class="dialog-intro">カートに商品が入っていません。</p>';$('#cart-total').textContent=yen(Object.entries(cart).reduce((s,[id,q])=>s+PRODUCTS.find(p=>p.id===id).price*q,0))}
function detail(id){const p=PRODUCTS.find(p=>p.id===id);$('#detail-dialog').innerHTML=`<button class="close" data-close aria-label="閉じる">×</button><p class="eyebrow">CARD DETAILS</p><div class="detail-image">${productImage(p)}</div><p class="product-meta">${esc(p.series)} · ${esc(p.rarity)}</p><h2>${esc(p.name)}</h2><p class="price">${yen(p.price)}<small>税込</small></p><p class="dialog-intro">状態：サンプル（参考画像）<br>デモ在庫：${p.stock} 枚</p><button class="primary full" data-add="${id}" ${p.stock?'':'disabled'}>${p.stock?'カートに入れる':'売り切れ'}</button><p class="sample-note">商品画像は参考画像です。実際の販売商品ではありません。</p>`;$('#detail-dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.add)add(b.dataset.add);if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.game){game=b.dataset.game;document.querySelectorAll('[data-game]').forEach(el=>el.classList.toggle('active',el===b));render()}if(b.dataset.minus){const id=b.dataset.minus;if(--cart[id]<=0)delete cart[id];save();renderCart()}if(b.dataset.remove){delete cart[b.dataset.remove];save();renderCart()}});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();render()});$('#search').addEventListener('input',render);document.querySelectorAll('aside input,aside select,#sort').forEach(el=>el.addEventListener('change',render));$('#reset').onclick=reset;$('#empty-reset').onclick=reset;$('#login-open').onclick=()=>{$('#login-message').textContent='';$('#login-dialog').showModal()};$('#cart-open').onclick=()=>{renderCart();$('#cart-dialog').showModal()};$('#login-form').addEventListener('submit',e=>{e.preventDefault();$('#login-message').textContent='現在、ログイン機能は準備中です。入力内容は送信・保存されません。';e.target.reset()});document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{if(d.id==='login-dialog')$('#login-form').reset()})});save();render();

function safeImage(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:''}catch{return ''}}
function productImage(p,lazy=false){const url=safeImage(p.image);return url?`<img src="${esc(url)}" alt="${esc(p.name)}" ${lazy?'loading="lazy"':''}>`:'<span class="no-image">画像未登録</span>'}
